// Boot loader + service-worker bridge (GD call Oct 30: lighter precache + progress bar).
// The SW (sw.js, generated by build.py write_pwa) installs the core set (shell + plaza/lane/mossglen/hollows) and reports
// real file/byte progress by postMessage; everything else is lazy (cache-first, network fallback) plus a throttled background fill.
// drawBootProgress(frac, label) is the ONE drawing hook: Hearthmoor Art's frames replace its body later.

const el = (id) => document.getElementById(id);

// ---- the one drawing function: Hearthmoor Art's neon bar (art/ui/loading-bar/, GD-approved Oct 30), canvas 160x14 at integer
// scale on the 640x360 UI base (x3 at 1920x1080), nearest-neighbour; #2a2458 behind the track. If any image fails to load the
// CSS placeholder (cyan on dark) draws instead. Reduced motion: static fill tile, endcap frame 0, flash frame 0.
const ART = 'art/ui/loading-bar/';
const LB = { ok: null, img: {}, frac: 0, label: '', t0: 0, flashAt: 0, raf: 0 };
const RM = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;
function loadArt() {
  if (LB.ok !== null) return;
  LB.ok = false;
  const names = { frame: 'frame.png', full: 'frame_full.png', tile: 'fill_tile.png', shimmer: 'anim/fill_shimmer_8f.png', flash: 'anim/fill_flash_4f.png', cap: 'anim/endcap_glow_4f.png' };
  Promise.all(Object.entries(names).map(([k, f]) => new Promise((ok, no) => { const im = new Image(); im.onload = () => { LB.img[k] = im; ok(); }; im.onerror = no; im.src = ART + f; })))
    .then(() => { LB.ok = true; LB.t0 = performance.now(); paintArt(); }, () => { LB.ok = false; LB.failed = true; drawPlaceholder(LB.frac, LB.label); });
}
function drawPlaceholder(f, label) {
  const bar = el('bootbar'), fill = el('bootfill'), cv = el('bootart');
  if (cv) cv.hidden = true;
  if (!bar || !fill) return;
  bar.hidden = false; fill.style.width = (f * 100).toFixed(1) + '%';
}
function paintArt() {
  const cv = el('bootart'); if (!cv || !LB.ok) return;
  const b = el('boot'); const live = b && !b.classList.contains('gone');
  const sc = Math.max(1, Math.min(3, Math.floor(Math.min(innerWidth / 640, innerHeight / 360)) || 1));
  cv.hidden = false; cv.style.width = 160 * sc + 'px'; cv.style.height = 14 * sc + 'px';
  const bar = el('bootbar'); if (bar) bar.hidden = true;
  const g = cv.getContext('2d'); g.imageSmoothingEnabled = false; g.clearRect(0, 0, 160, 14);
  const I = LB.img, now = performance.now(), f = LB.frac, px = Math.round(148 * f);
  g.fillStyle = '#2a2458'; g.fillRect(6, 4, 148, 6);
  let flashF = -1;
  if (f >= 1) { if (!LB.flashAt) LB.flashAt = now; flashF = RM ? 0 : Math.min(3, Math.floor((now - LB.flashAt) / 80)); }
  if (px > 0) {
    g.save(); g.beginPath(); g.rect(6, 4, px, 6); g.clip();
    const src = flashF >= 0 && flashF < 3 ? I.flash : RM ? I.tile : I.shimmer;
    const fr = flashF >= 0 ? flashF : RM ? 0 : Math.floor((now - LB.t0) / 90) % 8;
    for (let x = 0; x < px; x += 16) src === I.tile ? g.drawImage(src, 6 + x, 4) : g.drawImage(src, fr * 16, 0, 16, 6, 6 + x, 4, 16, 6);
    g.restore();
  }
  g.drawImage(flashF >= 0 && flashF < 3 ? I.full : I.frame, 0, 0);
  if (px > 0 && f < 1) { const cf = RM ? 0 : Math.floor((now - LB.t0) / 120) % 4; g.drawImage(I.cap, cf * 4, 0, 4, 10, 6 + px - 3, 2, 4, 10); }
  cancelAnimationFrame(LB.raf);
  if (live && !(flashF >= 3 || (RM && f >= 1))) LB.raf = requestAnimationFrame(paintArt);
}
export function drawBootProgress(frac, label) {
  const f = Math.max(0, Math.min(1, frac || 0));
  LB.frac = f; LB.label = label || '';
  const txt = el('bootpct'); if (txt) txt.textContent = label || Math.round(f * 100) + '%';
  loadArt();
  if (LB.ok) paintArt(); else drawPlaceholder(f, label);   // placeholder while the art loads, and for good if it fails
}
// tiny background-fill indicator: a 2px cyan line at the top edge, gone when the fill ends
function drawFillLine(frac) {
  const l = el('bgfill'); if (!l) return;
  if (frac == null || frac >= 1) { l.hidden = true; return; }
  l.hidden = false; l.style.width = (Math.max(0, frac) * 100).toFixed(1) + '%';
}

const S = { frac: 0, swCore: null, booted: false, lazy: null, fill: null, filling: false };
export const loaderState = () => ({ frac: S.frac, swCore: S.swCore, lazy: S.lazy, booted: S.booted });
const bootGone = () => { const b = el('boot'); return !b || b.classList.contains('gone'); };
function show(frac, label) { if (frac < S.frac) return; S.frac = frac; if (!bootGone()) drawBootProgress(frac, label); }

// without a SW progress feed (QA, ?nosw, first paint before the SW speaks): real bytes the page has loaded so far
// (resource timing) against the bytes the plaza boot needs, capped below 1 until the engine opens its gate
let expectBytes = 0, po = null;
function pageBytes() {
  let n = 0; for (const r of performance.getEntriesByType('resource')) n += r.decodedBodySize || r.encodedBodySize || 0; return n;
}
export function startBootProgress(expect = 25e6) {   // ~25 MB: measured plaza/title boot at b8bed2b (573 requests)
  expectBytes = expect; drawBootProgress(0, 'loading Hearthmoor…');
  const tick = () => {
    if (bootGone()) { S.booted = true; return; }
    const sh = S.swCore; show(Math.min(0.97, pageBytes() / expectBytes), sh && !sh.done ? `caching ${sh.files} / ${sh.nfiles}` : undefined);
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}
export function bootDone() { S.booted = true; drawBootProgress(1); }

// ---- SW bridge
const ask = (msg, ms = 120000) => new Promise((ok) => {
  const sw = navigator.serviceWorker && navigator.serviceWorker.controller;
  if (!sw) return ok(null);
  const ch = new MessageChannel(); const t = setTimeout(() => ok(null), ms);
  ch.port1.onmessage = (e) => { clearTimeout(t); ok(e.data); };
  sw.postMessage(msg, [ch.port2]);
});
export function registerSW(enabled) {
  if (!enabled || !('serviceWorker' in navigator)) return null;
  navigator.serviceWorker.addEventListener('message', (e) => {
    const d = e.data || {};
    if (d.type === 'hm-sw-fill') { S.fill = d; if (!d.complete && S.filling) setTimeout(nudge, 1000); return; }   // next time-boxed batch
    if (d.type !== 'hm-sw-progress') return;
    const frac = d.total ? d.bytes / d.total : d.files / d.nfiles;
    if (d.kind === 'shell') S.swCore = { files: d.files, nfiles: d.nfiles, bytes: d.bytes, total: d.total, done: !!d.done };
    else if (d.kind === 'first' || d.kind === 'lazy') { S.lazy = { phase: d.kind, files: d.files, nfiles: d.nfiles, done: !!d.done && d.kind === 'lazy', nfailed: d.nfailed || 0 };
      if (bootGone()) drawFillLine(S.lazy.done ? 1 : (d.kind === 'first' ? 0.25 * frac : 0.25 + 0.75 * frac)); }
  });
  return navigator.serviceWorker.register('sw.js').catch((err) => { console.warn('[hearthmoor] service worker registration failed', err); return null; });
}
// background fill once play has started: the SW works in time-boxed batches (first realm, then lazy areas + audio, throttled);
// the page asks for the next batch when one ends, and re-nudges every minute in case the browser stopped the worker
let fillGap = 60;
function nudge() { const c = navigator.serviceWorker && navigator.serviceWorker.controller; if (c && !(S.lazy && S.lazy.done)) c.postMessage({ type: 'hm-fill', gap: fillGap }); }
export function startBackgroundFill(gap = 60) {
  if (!('serviceWorker' in navigator)) return;
  fillGap = gap; S.filling = true;
  if (navigator.serviceWorker.controller) nudge(); else navigator.serviceWorker.addEventListener('controllerchange', nudge, { once: true });
  const iv = setInterval(() => { if (S.lazy && S.lazy.done) clearInterval(iv); else nudge(); }, 60000);
}
// before booting a lazy area: true if it is (now) fully cached or there is no SW in charge; false offline with files missing
export async function ensureArea(id, coreAreas) {
  if (coreAreas.includes(id) || !navigator.serviceWorker || !navigator.serviceWorker.controller) return true;
  const r = await ask({ type: 'hm-area', id });
  return !r || r.ok;
}
export const swStatus = () => ask({ type: 'hm-status' }, 5000);
